1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	</style>
57	</head>
58	<body>
59	<div class="calc">
60	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
61	  <div class="keys">
62	    <button class="clear wide" data-testid="key-clear">AC</button>
63	    <button class="op" data-testid="key-div" data-op="/">÷</button>
64	    <button class="op" data-testid="key-mul" data-op="*">×</button>
65	
66	    <button data-testid="key-7">7</button>
67	    <button data-testid="key-8">8</button>
68	    <button data-testid="key-9">9</button>
69	    <button class="op" data-testid="key-sub" data-op="-">−</button>
70	
71	    <button data-testid="key-4">4</button>
72	    <button data-testid="key-5">5</button>
73	    <button data-testid="key-6">6</button>
74	    <button class="op" data-testid="key-add" data-op="+">+</button>
75	
76	    <button data-testid="key-1">1</button>
77	    <button data-testid="key-2">2</button>
78	    <button data-testid="key-3">3</button>
79	    <button class="op" data-testid="key-equals">=</button>
80	
81	    <button class="wide" data-testid="key-0">0</button>
82	    <button data-testid="key-dot">.</button>
83	  </div>
84	</div>
85	<script>
86	  var display = document.querySelector('[data-testid="calc-display"]');
87	
88	  var state = {
89	    entry: '0',       // text of the number being shown/typed
90	    stored: null,     // left operand
91	    op: null,         // pending operator
92	    fresh: true,      // next digit starts a new entry
93	    typed: false,     // entry was typed by the user (shown as typed, not formatted)
94	    error: false
95	  };
96	
97	  // [REQ-003] Presentation only: at most 10 significant digits, no trailing
98	  // zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
99	  function formatNumber(v) {
100	    var r = Number(v.toPrecision(10));
101	    if (r === 0) return '0';
102	    var abs = Math.abs(r);
103	    if (abs >= 1e10 || abs < 1e-9) {
104	      return r.toExponential(9).replace(/\.?0+e/, 'e');
105	    }
106	    var e = Math.floor(Math.log10(abs));
107	    var s = r.toFixed(Math.max(0, 10 - e));
108	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
109	    return s;
110	  }
111	
112	  // [REQ-001]
113	  function compute(a, op, b) {
114	    switch (op) {
115	      case '+': return a + b;
116	      case '-': return a - b;
117	      case '*': return a * b;
118	      case '/': return a / b;
119	    }
120	    return b;
121	  }
122	
123	  // [REQ-001]
124	  // [REQ-003] Rounding happens here only; data-value keeps the exact value.
125	  function render() {
126	    var value = Number(state.entry);
127	    display.textContent = state.error ? 'Error' : (state.typed ? state.entry : formatNumber(value));
128	    display.setAttribute('data-value', state.error ? 'NaN' : String(value));
129	    display.setAttribute('data-error', state.error ? 'true' : 'false');
130	    document.querySelectorAll('button[data-op]').forEach(function (b) {
131	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
132	    });
133	  }
134	
135	  // [REQ-001]
136	  // [REQ-003] Division by zero (non-finite result) enters the error state.
137	  // String(value) is exact: Number(String(v)) === v.
138	  function setResult(value) {
139	    if (!isFinite(value)) {
140	      state.error = true;
141	      state.entry = '0';
142	      state.stored = null;
143	      state.op = null;
144	    } else {
145	      state.entry = String(value);
146	    }
147	    state.typed = false;
148	    state.fresh = true;
149	  }
150	
151	  // [REQ-001]
152	  // [REQ-003] Ignored in the error state; only clear leaves it.
153	  function inputDigit(d) {
154	    if (state.error) return;
155	    state.typed = true;
156	    if (state.fresh) {
157	      state.entry = d;
158	      state.fresh = false;
159	    } else {
160	      state.entry = state.entry === '0' ? d : state.entry + d;
161	    }
162	  }
163	
164	  // [REQ-001]
165	  // [REQ-003] Ignored in the error state.
166	  function inputDot() {
167	    if (state.error) return;
168	    state.typed = true;
169	    if (state.fresh) {
170	      state.entry = '0.';
171	      state.fresh = false;
172	    } else if (state.entry.indexOf('.') === -1) {
173	      state.entry += '.';
174	    }
175	  }
176	
177	  // [REQ-001]
178	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
179	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
180	  function inputOperator(op) {
181	    if (state.error) return;
182	    if (state.op !== null && !state.fresh) {
183	      setResult(compute(state.stored, state.op, Number(state.entry)));
184	      if (state.error) return;
185	    }
186	    state.stored = Number(state.entry);
187	    state.op = op;
188	    state.fresh = true;
189	  }
190	
191	  // [REQ-001]
192	  function equals() {
193	    if (state.error || state.op === null) return;
194	    var result = compute(state.stored, state.op, Number(state.entry));
195	    state.stored = null;
196	    state.op = null;
197	    setResult(result);
198	  }
199	
200	  // [REQ-001]
201	  function clearAll() {
202	    state.entry = '0';
203	    state.stored = null;
204	    state.op = null;
205	    state.fresh = true;
206	    state.typed = false;
207	    state.error = false;
208	  }
209	
210	  document.querySelector('.keys').addEventListener('click', function (e) {
211	    var btn = e.target.closest('button');
212	    if (!btn) return;
213	    var id = btn.getAttribute('data-testid');
214	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
215	    else if (id === 'key-dot') inputDot();
216	    else if (id === 'key-equals') equals();
217	    else if (id === 'key-clear') clearAll();
218	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
219	    render();
220	  });
221	
222	  render();
223	</script>
224	</body>
225	</html>
